import{_ as u,a0 as l,w as p,s as r,ao as a,I as i,x as n,a1 as e,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"有理想，有追求的系統管理員會在 Linux 中成長 | LCTT x X-CMD","titleTemplate":false,"description":"有理想，有追求的系統管理員會在 Linux 中成長 | LCTT (201610) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"有理想，有追求的系統管理員會在 Linux 中成長 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"有理想，有追求的系統管理員會在 Linux 中成長 | LCTT (201610) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201610/20160510 Aspiring sys admin works his way up in Linux","title":"有理想，有追求的系統管理員會在 Linux 中成長","tag":"201610","desc":""},"relativePath":"201610/20160510 Aspiring sys admin works his way up in Linux.md","filePath":"[post].md"}'),T={name:"201610/20160510 Aspiring sys admin works his way up in Linux.md"};function x(L,t,m,f,d,C){const s=l("Link");return p(),r("div",null,[t[10]||(t[10]=a("",10)),i("p",null,[t[1]||(t[1]=n("我對開源做貢獻已經有好一陣子了。剛開始時是為 xTuple ERP（LCTT 譯註：世界領先的開源 ERP 軟件）做翻譯工作（英語譯德語），現在已經轉為在 Twitter 上做 Mozilla 的“客户服務”，提交 bug 報告等。我為自由和開源軟件做推廣宣傳（取得了不同程度的成功）並且盡我所能在財政方面支持一些 FOSS（LCTT 譯註：自由及開源軟件）倡導組織（DuckDuckGo、bof.nl、EFF、GIMP、LibreCAD、維基百科以及其他）。目前我也在準備設立一個本地的隱私咖啡館（LCTT 譯註：這是荷蘭的一個旨在強化網上個人隱私安全的咖啡館/志願者組織，參見： ",-1)),e(s,{href:"https://privacycafe.bof.nl/%EF%BC%89%E3%80%82"},{default:o(()=>[...t[0]||(t[0]=[n("https://privacycafe.bof.nl/）。",-1)])]),_:1})]),t[11]||(t[11]=i("p",null,"除此之外，我已經開始寫我的第一本書。這應該是一本涉及計算機隱私和安全領域的簡易實用手冊，適用於普通計算機用户，我希望它能在今年年底自主出版。（這本書遵循知識共享許可協議 CC。）至於這本書的內容，正如你預料的那樣我會詳細解釋為什麼隱私如此重要，以及“我沒有什麼需要隱藏“這種思想錯的有多麼離譜。但是最主要的部分還是指導讀者如何避免讓人討厭的廣告追蹤，加密你的硬盤和郵件，通過 OTR（LCTT 譯註：一種安全協議，為即時通訊提供加密保護）網上聊天，如何使用 TOR（LCTT 譯註：第二代洋葱路由，可以在因特網上進行匿名交流）等等。雖然起初説這是一個手冊，但我儘量會使用隨和的語調來敍述，並且會根據精彩的我親身經歷的故事讓它更加通俗易懂。",-1)),t[12]||(t[12]=i("p",null,"我依然愛着我所有的 Mac，只要買得起（主要因為它那偉大的構造），我還會使用它們，但是我的 Linux 一直在虛擬機裏完成我的幾乎所有的日常工作。沒有什麼不可思議的，不是自誇：文檔編輯（LibreOffice 和 Scribus），建立我的網頁和Blog（Wordpress 和 Jekyll），編輯圖片（Shotwell 和 Gimp），聽音樂（Rhythmbox），以及幾乎其他任何工作。",-1)),t[13]||(t[13]=i("p",null,"不論我最後怎麼找到工作，Linux 永遠都是我必用的操作系統。",-1)),t[14]||(t[14]=i("hr",null,null,-1)),i("p",null,[t[3]||(t[3]=n("via: ",-1)),e(s,{href:"https://opensource.com/life/16/5/my-linux-story-rene-raggl"},{default:o(()=>[...t[2]||(t[2]=[n("https://opensource.com/life/16/5/my-linux-story-rene-raggl",-1)])]),_:1})]),i("p",null,[t[7]||(t[7]=n("作者：",-1)),e(s,{href:"https://opensource.com/users/rraggl"},{default:o(()=>[...t[4]||(t[4]=[n("Rene Raggl",-1)])]),_:1}),t[8]||(t[8]=n(" 譯者：",-1)),e(s,{href:"https://github.com/fuowang"},{default:o(()=>[...t[5]||(t[5]=[n("fuowang",-1)])]),_:1}),t[9]||(t[9]=n(" 校對：",-1)),e(s,{href:"https://github.com/wxy"},{default:o(()=>[...t[6]||(t[6]=[n("wxy",-1)])]),_:1})])])}const b=u(T,[["render",x]]);export{w as __pageData,b as default};
